import java.util.*;

public class Main {
    private static int maxOutsideWord(String text) {
        int max = 0;
        for (String word : text.split("_")) {
            max = Math.max(max, word.length());
        }
        return max;
    }

    private static int countInsideWords(String text) {
        int count = 0;
        for (String word : text.split("_")) {
            if (!word.isEmpty()) {
                count++;
            }
        }
        return count;
    }

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int n = sc.nextInt();
        String s = sc.next();
        boolean openParenthesis = false;
        StringBuilder sb = new StringBuilder();
        List<Integer> outsideMaxes = new ArrayList<>();
        List<Integer> insideCounts = new ArrayList<>();
        for (int i = 0; i < n; i++) {
            char c = s.charAt(i);
            if (c == '(') {
                if (!openParenthesis) {
                    outsideMaxes.add(maxOutsideWord(sb.toString()));
                }
                openParenthesis = true;
                sb.setLength(0);
            } else if (c == ')') {
                openParenthesis = false;
                insideCounts.add(countInsideWords(sb.toString()));
                sb.setLength(0);
            } else {
                sb.append(c);
            }
        }
        outsideMaxes.add(maxOutsideWord(sb.toString()));
        int maxOutSide = 0;
        for (int m : outsideMaxes) {
            maxOutSide = Math.max(maxOutSide, m);
        }
        int nbrInside = 0;
        for (int c : insideCounts) {
            nbrInside += c;
        }
        System.out.println(maxOutSide + " " + nbrInside);
    }
}
